/* question carousel - this is above edits and todos */
.interactive-session .interactive-input-part > .chat-question-carousel-widget-container:empty,
.interactive-session .interactive-input-part .interactive-input-and-edit-session > .chat-question-carousel-widget-container:empty {
	display: none;
}

/* input specific styling - box look comes from the shared container rule below */
.interactive-session .interactive-input-part > .chat-question-carousel-widget-container .chat-question-carousel-container,
.interactive-session .interactive-input-part .interactive-input-and-edit-session > .chat-question-carousel-widget-container .chat-question-carousel-container {
	margin: 0;
}

/* general questions styling - matches the tool confirmation (permissions) box family */
.interactive-session .chat-question-carousel-container {
	margin: 8px 0;
	border: var(--vscode-strokeThickness) solid var(--vscode-input-border, var(--vscode-chat-requestBorder));
	border-radius: var(--vscode-cornerRadius-large);
	background-color: var(--vscode-panel-background);
	display: flex;
	flex-direction: column;
	overflow: hidden;
	container-type: inline-size;
	max-height: min(420px, 45vh);
	position: relative;
}

.interactive-session .chat-question-carousel-container:focus {
	outline: none;
}

.interactive-session .chat-question-carousel-container:focus-visible,
.interactive-session .chat-question-carousel-container:focus-within {
	border-color: var(--vscode-focusBorder);
}

/* in the agents window / editor the surface is the editor background */
.agent-sessions-workbench .interactive-session .chat-question-carousel-container,
.editor-instance .interactive-session .chat-question-carousel-container {
	background-color: var(--vscode-editor-background);
}

/* input part wrapper */
.interactive-session .interactive-input-part > .chat-question-carousel-widget-container,
.interactive-session .interactive-input-part .interactive-input-and-edit-session > .chat-question-carousel-widget-container {
	width: 100%;
	position: relative;
	display: flex;
	flex-direction: column;
	gap: 8px;
}

.interactive-session .interactive-input-part > .chat-question-carousel-widget-container:not(:empty),
.interactive-session .interactive-input-part .interactive-input-and-edit-session > .chat-question-carousel-widget-container:not(:empty) {
	margin-top: 8px;
}

.interactive-session .interactive-input-part > .chat-question-carousel-widget-container .chat-question-carousel-content,
.interactive-session .interactive-input-part .interactive-input-and-edit-session > .chat-question-carousel-widget-container .chat-question-carousel-content {
	min-height: 0;
}

/* container and header */
.interactive-session .chat-question-carousel-container .chat-question-carousel-content {
	display: flex;
	flex-direction: column;
	min-height: 0;
	overflow: hidden;

	.chat-question-header-row {
		display: flex;
		flex-direction: column;
		flex-shrink: 0;

		.chat-question-title-row {
			display: flex;
			justify-content: space-between;
			align-items: flex-start;
			gap: 8px;
			min-width: 0;
			padding: 8px 8px 8px 16px;
			border-bottom: 1px solid var(--vscode-chat-requestBorder);
		}

		.chat-question-title {
			flex: 1;
			min-width: 0;
			word-break: break-word;
			overflow-wrap: anywhere;
			white-space: normal;
			font-weight: var(--vscode-agents-fontWeight-semiBold);
			font-size: var(--vscode-agents-fontSize-heading3);
			margin: 0;
			user-select: text;
			-webkit-user-select: text;

			.rendered-markdown {
				a {
					color: var(--vscode-textLink-foreground);
				}

				a:hover,
				a:active {
					color: var(--vscode-textLink-activeForeground);
				}

				p {
					margin: 0;
				}
			}
		}

		.chat-question-header-actions {
			display: flex;
			align-items: center;
			gap: 4px;
			flex-shrink: 0;
		}

		.chat-question-focus-terminal-container {
			flex-shrink: 0;

			.monaco-button.chat-question-focus-terminal {
				min-width: 22px;
				width: 22px;
				height: 22px;
				padding: 0;
				border: none !important;
				box-shadow: none !important;
				background: transparent !important;
				color: var(--vscode-icon-foreground) !important;
			}

			.monaco-button.chat-question-focus-terminal:hover:not(.disabled) {
				background: var(--vscode-toolbar-hoverBackground) !important;
			}
		}

		.chat-question-close-container {
			flex-shrink: 0;

			.monaco-button.chat-question-close {
				min-width: 22px;
				width: 22px;
				height: 22px;
				padding: 0;
				border: none !important;
				box-shadow: none !important;
				background: transparent !important;
				color: var(--vscode-icon-foreground) !important;
			}

			.monaco-button.chat-question-close:hover:not(.disabled) {
				background: var(--vscode-toolbar-hoverBackground) !important;
			}
		}

		.monaco-button.chat-question-collapse-toggle {
			min-width: 22px;
			width: 22px;
			height: 22px;
			padding: 0;
			border: none !important;
			box-shadow: none !important;
			background: transparent !important;
			color: var(--vscode-icon-foreground) !important;
		}

		.monaco-button.chat-question-collapse-toggle:hover:not(.disabled) {
			background: var(--vscode-toolbar-hoverBackground) !important;
		}
	}
}

.interactive-session .chat-question-carousel-container.chat-question-carousel-collapsed {
	.chat-question-carousel-content {
		.chat-question-description,
		.chat-question-input-scrollable,
		.chat-question-validation-message {
			display: none;
		}
	}

	.chat-question-footer-row {
		display: none;
	}
}

/* questions list and freeform area */
.interactive-session .chat-question-carousel-container .chat-question-input-container {
	display: flex;
	flex-direction: column;
	padding: 8px 16px;
	min-width: 0;

	&::after {
		content: '';
		display: block;
		height: 8px;
		flex-shrink: 0;
	}

	/* some hackiness to get the focus looking right */
	.chat-question-list-item:focus,
	.chat-question-list:focus {
		outline: none;
	}

	.chat-question-list {
		display: flex;
		flex-direction: column;
		outline: none;
		padding: 0;

		.chat-question-list-item {
			display: flex;
			align-items: center;
			gap: 8px;
			padding: 6px 8px;
			cursor: pointer;
			border-radius: var(--vscode-cornerRadius-medium);
			user-select: none;

			.chat-question-list-indicator {
				width: 16px;
				height: 16px;
				display: flex;
				align-items: center;
				justify-content: center;
				flex-shrink: 0;
				margin-left: auto;
				align-self: flex-start;
				margin-top: 2px;
			}

			.chat-question-list-indicator.codicon-check {
				color: var(--vscode-list-activeSelectionForeground, var(--vscode-foreground));
			}

			/* Label in list item */
			.chat-question-list-label {
				font-size: var(--vscode-agents-fontSize-body2);
				font-weight: var(--vscode-agents-fontWeight-semiBold);
				flex: 1;
				word-wrap: break-word;
				overflow-wrap: break-word;
				display: flex;
				flex-direction: column;
			}

			.chat-question-list-label-title {
				font-weight: var(--vscode-agents-fontWeight-semiBold);
				line-height: 1.4;
			}

			.chat-question-list-label-desc {
				font-weight: var(--vscode-agents-fontWeight-regular);
				color: var(--vscode-descriptionForeground);
			}
		}

		.chat-question-list-item.has-description {
			align-items: flex-start;

			.chat-question-list-number {
				line-height: 1.4;
				font-size: var(--vscode-agents-fontSize-body2);
				font-weight: var(--vscode-agents-fontWeight-semiBold);
			}

			.chat-question-list-checkbox {
				/* Title line-height is ~17px (1.4 * body-s), checkbox is 16px: 1px offset */
				margin-top: 1px;
			}
		}

		.chat-question-list-item:hover {
			background-color: var(--vscode-list-hoverBackground);
		}

		/* Single-select: highlight entire row when selected (list not focused) */
		.chat-question-list-item.selected {
			background-color: var(--vscode-list-inactiveSelectionBackground, var(--vscode-list-hoverBackground));
			color: var(--vscode-list-inactiveSelectionForeground, var(--vscode-foreground));

			.chat-question-list-label,
			.chat-question-list-label-title {
				color: var(--vscode-list-inactiveSelectionForeground, var(--vscode-foreground));
			}

			.chat-question-list-label-desc {
				color: var(--vscode-list-inactiveSelectionForeground, var(--vscode-foreground));
			}

			.chat-question-list-indicator.codicon-check {
				color: var(--vscode-list-inactiveSelectionForeground, var(--vscode-foreground));
			}

			.chat-question-list-number {
				color: var(--vscode-list-inactiveSelectionForeground, var(--vscode-foreground));
			}
		}

		/* When the question list has focus, use active selection styling */
		.chat-question-list:focus .chat-question-list-item.selected {
			background-color: var(--vscode-list-activeSelectionBackground, var(--vscode-list-hoverBackground));
			color: var(--vscode-list-activeSelectionForeground, var(--vscode-foreground));

			.chat-question-label {
				color: var(--vscode-list-activeSelectionForeground, var(--vscode-foreground));
			}

			.chat-question-list-label-desc {
				color: var(--vscode-list-activeSelectionForeground, var(--vscode-foreground));
			}

			.chat-question-list-indicator.codicon-check {
				color: var(--vscode-list-activeSelectionForeground, var(--vscode-foreground));
			}

			.chat-question-list-number {
				color: var(--vscode-list-activeSelectionForeground, var(--vscode-foreground));
			}
		}
		.chat-question-list-item.selected:hover {
			background-color: var(--vscode-list-inactiveSelectionBackground, var(--vscode-list-hoverBackground));
		}

		.chat-question-list-item.multi-select:focus {
			outline: 1px solid var(--vscode-focusBorder);
			outline-offset: -1px;
		}

		/* Checkbox for multi-select */
		.chat-question-list-checkbox {
			flex-shrink: 0;
		}

		.chat-question-list-checkbox.monaco-custom-toggle {
			margin-right: 0;
		}
	}

	.chat-question-freeform {
		margin: 0;
		display: flex;
		flex-direction: row;
		align-items: center;
		padding: 4px 8px;
		gap: 8px;

		.chat-question-freeform-number {
			height: fit-content;
		}

		/* this is probably legacy too */
		.chat-question-freeform-label {
			font-size: var(--vscode-chat-font-size-body-s);
			color: var(--vscode-descriptionForeground);
		}

		.chat-question-freeform-textarea {
			width: 100%;
			min-height: 24px;
			max-height: 200px;
			padding: 3px 8px;
			border: 1px solid var(--vscode-input-border, var(--vscode-chat-requestBorder));
			background-color: var(--vscode-input-background);
			color: var(--vscode-input-foreground);
			border-radius: 4px;
			resize: none;
			font-family: var(--vscode-chat-font-family, inherit);
			font-size: var(--vscode-chat-font-size-body-s);
			box-sizing: border-box;
			overflow-y: hidden;
			align-content: center;
		}

		.chat-question-freeform-textarea:focus {
			outline: 1px solid var(--vscode-focusBorder);
			border-color: var(--vscode-focusBorder);
		}

		.chat-question-freeform-textarea::placeholder {
			color: var(--vscode-input-placeholderForeground);
		}

	}

	/* todo: change to use keybinding service so we don't have to recreate this */
	.chat-question-list-number,
	.chat-question-freeform-number {
		font-size: var(--vscode-agents-fontSize-body2);
		font-weight: var(--vscode-agents-fontWeight-semiBold);
		color: var(--vscode-descriptionForeground);
		flex-shrink: 0;
		min-width: 1ch;
		text-align: right;
	}
}

.interactive-session .chat-question-carousel-container .chat-question-input-container > * {
	flex-shrink: 0;
}

.interactive-session .chat-question-carousel-container .chat-question-input-scrollable {
	flex: 0 1 auto;
	min-height: 0;
	overscroll-behavior: contain;
}

/* footer with nav arrows, step indicator, and submit */
.interactive-session .chat-question-carousel-container .chat-question-footer-row {
	display: flex;
	justify-content: space-between;
	align-items: center;
	padding: 4px 8px;
	border-top: 1px solid var(--vscode-chat-requestBorder);
	flex-shrink: 0;

	.chat-question-footer-left {
		display: flex;
		align-items: center;
		gap: 8px;
	}

	.chat-question-footer-right {
		display: flex;
		align-items: center;
		gap: 8px;
	}

	.chat-question-nav-arrows {
		display: flex;
		align-items: center;
		gap: 4px;
	}

	.monaco-button.chat-question-nav-arrow {
		min-width: 22px;
		width: 22px;
		height: 22px;
		padding: 0;
		border: none !important;
		box-shadow: none !important;
		background: transparent !important;
		color: var(--vscode-foreground) !important;
	}

	.monaco-button.chat-question-nav-arrow:hover:not(.disabled) {
		background: var(--vscode-toolbar-hoverBackground) !important;
	}

	.monaco-button.chat-question-nav-arrow.disabled {
		opacity: 0.4;
	}

	.chat-question-step-indicator {
		font-size: var(--vscode-chat-font-size-body-s);
		color: var(--vscode-descriptionForeground);
	}

	.chat-question-submit-hint {
		font-size: var(--vscode-agents-fontSize-body2);
		color: var(--vscode-descriptionForeground);
	}

	.monaco-button.chat-question-submit-button {
		background: var(--vscode-button-background) !important;
		color: var(--vscode-button-foreground) !important;
		height: 22px;
		width: auto;
		flex: 0 0 auto;
		min-width: auto;
		padding: 0 8px;
	}

	.monaco-button.chat-question-submit-button:hover:not(.disabled) {
		background: var(--vscode-button-hoverBackground) !important;
	}
}

/* user-select: text for elicitation dialog text areas */
.interactive-session .chat-question-carousel-container .chat-question-detailed-message,
.interactive-session .chat-question-carousel-container .chat-question-description {
	user-select: text;
	-webkit-user-select: text;
}

/* carousel-level message (e.g. from MCP elicitation) */
.interactive-session .chat-question-carousel-container .chat-question-carousel-message {
	padding: 8px 16px 0;
	font-size: var(--vscode-chat-font-size-body-s);
	color: var(--vscode-descriptionForeground);
	max-height: min(220px, 25vh);
	overflow-y: auto;
	overscroll-behavior: contain;
	user-select: text;
	-webkit-user-select: text;

	.rendered-markdown p {
		margin: 0;
	}
}

/* field description below question title */
.interactive-session .chat-question-carousel-container .chat-question-description {
	padding: 4px 16px;
	font-size: var(--vscode-chat-font-size-body-s);
	color: var(--vscode-descriptionForeground);
}

/* validation error message below input area */
.interactive-session .chat-question-carousel-container .chat-question-validation-message {
	padding: 0 16px 4px;
	font-size: var(--vscode-chat-font-size-body-s);
	color: var(--vscode-editorWarning-foreground);
	flex-shrink: 0;
}

/* summary (after finished) */
.interactive-session .chat-question-carousel-summary {
	display: flex;
	flex-direction: column;
	gap: 8px;
	padding: 8px;

	.chat-question-summary-item {
		display: flex;
		flex-direction: column;
		gap: 0;
		font-size: var(--vscode-chat-font-size-body-s);
	}

	.chat-question-summary-label {
		color: var(--vscode-descriptionForeground);
		word-wrap: break-word;
		overflow-wrap: break-word;
	}

	.chat-question-summary-answer-title {
		color: var(--vscode-foreground);
		font-weight: 600;
		word-wrap: break-word;
		overflow-wrap: break-word;
	}

	.chat-question-summary-answer-desc {
		color: var(--vscode-foreground);
		word-wrap: break-word;
		overflow-wrap: break-word;
	}

	.chat-question-summary-skipped,
	.chat-question-summary-answered {
		color: var(--vscode-descriptionForeground);
		font-style: italic;
		font-size: var(--vscode-chat-font-size-body-s);
	}
}

.interactive-session .chat-question-carousel-container.chat-question-carousel-conversation.chat-question-carousel-used {
	max-height: none;
	overflow: visible;
	border: none;
	background: transparent;
}

.interactive-session .chat-question-carousel-container.chat-question-carousel-conversation.chat-question-carousel-used:focus-visible {
	outline: var(--vscode-strokeThickness) solid var(--vscode-focusBorder);
	outline-offset: calc(-1 * var(--vscode-strokeThickness));
}

.interactive-session .chat-question-carousel-container.chat-question-carousel-conversation.chat-question-carousel-used:focus-within:not(:focus-visible) {
	border-color: transparent;
	outline: none;
}

.interactive-session .chat-question-carousel-conversation-summary {
	gap: var(--vscode-spacing-size120);
	padding: var(--vscode-spacing-size80) 0;

	.chat-question-summary-item {
		gap: var(--vscode-spacing-size60);
		padding: var(--vscode-spacing-size40) 0 0;
		font-size: var(--vscode-agents-fontSize-body1);
	}

	.chat-question-summary-question {
		display: flex;
		gap: var(--vscode-spacing-size40);
		color: var(--vscode-descriptionForeground);
	}

	.chat-question-summary-prefix {
		flex-shrink: 0;
		font-weight: var(--vscode-agents-fontWeight-semiBold);
	}

	.chat-question-summary-question-value,
	.chat-question-summary-answer-value {
		overflow: hidden;
		text-overflow: ellipsis;
		white-space: nowrap;
	}

	.chat-question-summary-decision {
		position: relative;
		display: flex;
		flex-direction: column;
		padding-left: var(--vscode-spacing-size160);
	}

	.chat-question-summary-decision::before {
		position: absolute;
		top: calc(-1 * var(--vscode-spacing-size40));
		left: var(--vscode-spacing-size40);
		width: var(--vscode-spacing-size60);
		height: var(--vscode-spacing-size160);
		border-bottom: var(--vscode-strokeThickness) solid var(--vscode-chat-requestBorder);
		border-left: var(--vscode-strokeThickness) solid var(--vscode-chat-requestBorder);
		border-bottom-left-radius: var(--vscode-cornerRadius-medium);
		content: '';
		pointer-events: none;
	}

	.chat-question-summary-answer-icon {
		flex: 0 0 var(--vscode-codiconFontSize-compact);
		font-size: var(--vscode-codiconFontSize-compact);
		line-height: 1;
	}

	.chat-question-answer-collapsible {
		min-width: 0;
		margin-bottom: 0;
	}

	.chat-question-answer-collapsible > .chat-used-context-label .monaco-button {
		align-items: center;
		max-width: 100%;
	}

	.chat-question-answer-collapsible:not(.chat-question-answer-expandable) > .chat-used-context-label .monaco-button {
		cursor: default;
		pointer-events: none;
		user-select: none;
	}

	.chat-question-answer-collapsible > .chat-used-context-label .monaco-button-mdlabel {
		display: flex;
		flex: 1;
		align-items: center;
		gap: var(--vscode-spacing-size40);
		white-space: normal;
		width: 100%;
	}

	.chat-question-answer-collapsible .chat-question-summary-answer-icon,
	.chat-question-answer-collapsible .chat-collapsible-hover-chevron {
		align-self: center;
		margin-top: 2px;
	}

	.chat-question-answer-expandable .chat-collapsible-hover-chevron {
		flex-shrink: 0;
		margin-left: var(--vscode-spacing-size20);
		line-height: 1;
		opacity: 1;
	}

	.chat-question-summary-option-details {
		margin-bottom: 0;
		padding: var(--vscode-spacing-size100);
		border: var(--vscode-strokeThickness) solid var(--vscode-widget-border);
		border-radius: var(--vscode-cornerRadius-medium);
		background: var(--vscode-editorWidget-background);
		color: var(--vscode-descriptionForeground);
		font-size: var(--vscode-chat-font-size-body-s)
	}

	.chat-question-summary-options-title {
		margin-bottom: var(--vscode-spacing-size40);
		padding: 0 var(--vscode-spacing-size80) var(--vscode-spacing-size40);
		border-bottom: var(--vscode-strokeThickness) solid color-mix(in srgb, var(--vscode-widget-border) 70%, transparent);
		color: var(--vscode-foreground);
		font-size: var(--vscode-agents-fontSize-label1);
	}

	.chat-question-summary-option-list {
		display: flex;
		flex-direction: column;
		gap: 0;
		margin: 0;
		padding: 0;
		list-style: none;
	}

	.chat-question-summary-option {
		display: flex;
		align-items: center;
		gap: var(--vscode-spacing-size80);
		padding: var(--vscode-spacing-size40) var(--vscode-spacing-size80);
		border-radius: var(--vscode-cornerRadius-small);
	}

	.chat-question-summary-option.selected {
		background: var(--vscode-list-inactiveSelectionBackground);
		color: var(--vscode-foreground);
	}

	.chat-question-summary-option-label {
		flex: 1;
	}

	.chat-question-summary-option-selected {
		display: flex;
		flex-shrink: 0;
		align-items: center;
		color: inherit;
	}

	.chat-question-summary-option-selected > .codicon {
		font-size: var(--vscode-codiconFontSize-compact);
	}
}
